<script setup lang="ts">import { reactive } from "vue"; import { ElMessage } from "element-plus"; import { post } from "@/api/client"; const props = withDefaults(defineProps<{ readonly endpoint?: string; readonly title?: string }>(), { endpoint: "/inbounds", title: "新建入库" }); const form = reactive({ items: [{ item_id: "", location_id: "", quantity: 1 }] }); function add(): void { form.items.push({ item_id: "", location_id: "", quantity: 1 }) } async function save(): Promise<void> { await post(props.endpoint, form); ElMessage.success("提交成功") }</script>
<template><el-card><template #header>{{ props.title }}</template><el-form v-for="(item, index) in form.items" :key="index" inline><el-form-item label="商品 ID"><el-input v-model="item.item_id" /></el-form-item><el-form-item label="库位 ID"><el-input v-model="item.location_id" /></el-form-item><el-form-item label="数量"><el-input-number v-model="item.quantity" :min="1" /></el-form-item></el-form><el-button @click="add">添加明细</el-button><el-button type="primary" @click="save">提交</el-button></el-card></template>
